1	// Package webhooks sends an organization's events to its webhook endpoints.
2	package webhooks
3	
4	import (
5		"bytes"
6		"context"
7		"crypto/hmac"
8		"crypto/sha256"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"io"
14		"net"
15		"net/http"
16		"net/url"
17		"slices"
18		"time"
19	
20		"example.com/tally/internal/clock"
21		"example.com/tally/internal/store"
22	)
23	
24	// Doer sends HTTP requests (an *http.Client).
25	type Doer interface {
26		Do(*http.Request) (*http.Response, error)
27	}
28	
29	// Resolver looks up host names (a *net.Resolver).
30	type Resolver interface {
31		LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error)
32	}
33	
34	// Options configure a Service.
35	type Options struct {
36		Store *store.Store
37		Clock clock.Clock
38		// Doer sends the deliveries; nil means an HTTP client with a 10 second timeout that does not follow redirects.
39		Doer Doer
40		// Resolver checks endpoint hosts; nil means net.DefaultResolver.
41		Resolver Resolver
42	}
43	
44	// Service manages endpoints' URLs and sends deliveries.
45	type Service struct {
46		store    *store.Store
47		clock    clock.Clock
48		doer     Doer
49		resolver Resolver
50	}
51	
52	// New returns a Service.
53	func New(opt Options) *Service {
54		s := &Service{store: opt.Store, clock: opt.Clock, doer: opt.Doer, resolver: opt.Resolver}
55		if s.clock == nil {
56			s.clock = clock.Real{}
57		}
58		if s.doer == nil {
59			s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
60		}
61		if s.resolver == nil {
62			s.resolver = net.DefaultResolver
63		}
64		return s
65	}
66	
67	// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
68	var EventTypes = []string{
69		"customer.created", "customer.updated", "customer.deleted",
70		"subscription.created", "subscription.updated", "subscription.canceled",
71		"invoice.created", "invoice.paid", "invoice.payment_failed", "invoice.voided",
72	}
73	
74	// Errors.
75	var (
76		ErrInvalidURL    = errors.New("invalid webhook URL")
77		ErrInvalidEvents = errors.New("invalid event types")
78	)
79	
80	// CheckURL checks a webhook URL before it is saved: an absolute http or https URL whose host resolves.
81	func (s *Service) CheckURL(ctx context.Context, raw string) error {
82		u, err := url.Parse(raw)
83		if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
84			return fmt.Errorf("%w: use an absolute http or https URL", ErrInvalidURL)
85		}
86		host := u.Hostname()
87		if net.ParseIP(host) != nil {
88			return nil
89		}
90		addrs, err := s.resolver.LookupIPAddr(ctx, host)
91		if err != nil || len(addrs) == 0 {
92			return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
93		}
94		return nil
95	}
96	
97	// CheckEvents checks an endpoint's event types.
98	func CheckEvents(types []string) error {
99		if len(types) == 0 {
100			return fmt.Errorf("%w: name at least one event type, or \"*\"", ErrInvalidEvents)
101		}
102		for _, t := range types {
103			if t != "*" && !slices.Contains(EventTypes, t) {
104				return fmt.Errorf("%w: unknown event type %q", ErrInvalidEvents, t)
105			}
106		}
107		return nil
108	}
109	
110	// NewSecret returns a new signing secret for an endpoint.
111	func NewSecret() string { return store.NewToken("whsec_") }
112	
113	// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
114	func Sign(secret string, body []byte) string {
115		m := hmac.New(sha256.New, []byte(secret))
116		m.Write(body)
117		return hex.EncodeToString(m.Sum(nil))
118	}
119	
120	// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
121	// type. The deliveries are sent by RunDue.
122	func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
123		raw, err := json.Marshal(data)
124		if err != nil {
125			return err
126		}
127		now := s.clock.Now()
128		e, err := s.store.AddEvent(orgID, eventType, raw, now)
129		if err != nil {
130			return err
131		}
132		for _, ep := range s.store.WebhookEndpoints(orgID) {
133			if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
134				continue
135			}
136			next := now
137			if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
138				return err
139			}
140		}
141		return nil
142	}
143	
144	// RunDue attempts every delivery that is due and returns how many it attempted. Each delivery is attempted once: an answer
145	// with a 2xx status marks it succeeded, anything else failed.
146	func (s *Service) RunDue(ctx context.Context) (int, error) {
147		n := 0
148		for _, d := range s.store.DueDeliveries(s.clock.Now()) {
149			if err := ctx.Err(); err != nil {
150				return n, err
151			}
152			s.deliver(ctx, d)
153			n++
154		}
155		return n, nil
156	}
157	
158	// Body is what a delivery POSTs.
159	type Body struct {
160		ID        string          `json:"id"`
161		Type      string          `json:"type"`
162		CreatedAt time.Time       `json:"created_at"`
163		Data      json.RawMessage `json:"data"`
164	}
165	
166	func (s *Service) deliver(ctx context.Context, d store.Delivery) {
167		status, errText := 0, ""
168		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
169		e, eok := s.store.EventByID(d.EventID)
170		switch {
171		case !ok || !ep.Enabled:
172			errText = "the endpoint is disabled or was deleted"
173		case !eok:
174			errText = "the event no longer exists"
175		default:
176			status, errText = s.send(ctx, ep, e)
177		}
178		now := s.clock.Now()
179		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
180			d.Attempts++
181			d.LastAttemptAt = &now
182			d.NextAttemptAt = nil
183			d.ResponseStatus = status
184			d.Error = errText
185			if errText == "" {
186				d.Status = store.DeliverySucceeded
187			} else {
188				d.Status = store.DeliveryFailed
189			}
190			return nil
191		})
192	}
193	
194	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
195	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
196		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
197		if err != nil {
198			return 0, err.Error()
199		}
200		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
201		defer cancel()
202		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
203		if err != nil {
204			return 0, err.Error()
205		}
206		req.Header.Set("Content-Type", "application/json")
207		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
208		req.Header.Set("Tally-Event-Id", e.ID)
209		req.Header.Set("Tally-Event-Type", e.Type)
210		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
211		resp, err := s.doer.Do(req)
212		if err != nil {
213			return 0, err.Error()
214		}
215		defer resp.Body.Close()
216		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
217		if resp.StatusCode < 200 || resp.StatusCode > 299 {
218			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
219		}
220		return resp.StatusCode, ""
221	}
222

