// FakeHTTP plays the organizations' webhook receivers: it records every request and answers 200, or what Respond returns
// when it is set (a status code, or an error for a request that never got an answer).
type FakeHTTP struct {
	// Respond, when set, answers each request. Set it before requests are made, or between them.
	Respond func(r Request) (int, error)

	mu       sync.Mutex
	requests []Request
}

// Request is a request a FakeHTTP received.
type Request struct {
	Method string
	URL    string
	Header http.Header
	Body   []byte
}

// Do implements webhooks.Doer.
func (f *FakeHTTP) Do(req *http.Request) (*http.Response, error) {
	var body []byte
	if req.Body != nil {
		body, _ = io.ReadAll(req.Body)
		req.Body.Close()
	}
	r := Request{Method: req.Method, URL: req.URL.String(), Header: req.Header.Clone(), Body: body}
	f.mu.Lock()
	f.requests = append(f.requests, r)
	respond := f.Respond
	f.mu.Unlock()
	status := http.StatusOK
	if respond != nil {
		var err error
		if status, err = respond(r); err != nil {
			return nil, err
		}
	}
	return &http.Response{StatusCode: status, Status: http.StatusText(status), Header: http.Header{}, Body: io.NopCloser(strings.NewReader("")), Request: req}, nil
}

// Requests returns the requests received so far, oldest first.
func (f *FakeHTTP) Requests() []Request {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]Request(nil), f.requests...)
}

// FakeDNS answers host lookups from the addresses Set gave it. Other hosts do not resolve.
type FakeDNS struct {
	mu    sync.Mutex
	hosts map[string][]string
}

// Set makes host resolve to ips (none: the host does not resolve).
func (d *FakeDNS) Set(host string, ips ...string) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if d.hosts == nil {
		d.hosts = map[string][]string{}
	}
	d.hosts[strings.ToLower(host)] = ips
}

// LookupIPAddr implements webhooks.Resolver.
func (d *FakeDNS) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
	d.mu.Lock()
	ips := d.hosts[strings.ToLower(host)]
	d.mu.Unlock()
	if len(ips) == 0 {
		return nil, &net.DNSError{Err: "no such host", Name: host, IsNotFound: true}
	}
	out := make([]net.IPAddr, 0, len(ips))
	for _, s := range ips {
		ip := net.ParseIP(s)
		if ip == nil {
			return nil, fmt.Errorf("FakeDNS: %q is not an IP address", s)
		}
		out = append(out, net.IPAddr{IP: ip})
	}
	return out, nil
}
}

func TestWebhookEndpoints(t *testing.T) {
	e := apitest.New(t)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"customer.created"}}, &ep)
	if !ep.Enabled || !strings.HasPrefix(ep.Secret, "whsec_") {
		t.Fatalf("endpoint = %+v", ep)
	}
	for _, bad := range []map[string]any{
		{"url": "https://does-not-resolve.example/", "events": []string{"*"}},
		{"url": "not a url", "events": []string{"*"}},
	} {
		if r := e.Do("POST", "/v1/webhook-endpoints", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_url" {
			t.Fatalf("%v: %s", bad, r)
		}
	}
	if r := e.Do("POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/", "events": []string{"nope"}}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_events" {
		t.Fatalf("bad events: %s", r)
	}
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	if n, err := e.Webhooks.RunDue(context.Background()); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	if reqs := e.HTTP.Requests(); len(reqs) != 1 || !strings.Contains(string(reqs[0].Body), c.ID) {
		t.Fatalf("requests = %+v", reqs)
	}
	var ds struct{ Items []store.Delivery }
	e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+ep.ID+"/deliveries", e.Acme.Key, nil, &ds)
	if len(ds.Items) != 1 || ds.Items[0].Status != store.DeliverySucceeded {
		t.Fatalf("deliveries = %+v", ds)
	}
	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created", e.Acme.Key, nil, &evs)
	if len(evs.Items) != 1 {
		t.Fatalf("events = %+v", evs)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, map[string]any{"enabled": false}, &ep)
	if ep.Enabled {
		t.Fatal("still enabled")
	}
	e.CreateCustomer(e.Acme, "John", "john@example.com")
	if n, _ := e.Webhooks.RunDue(context.Background()); n != 0 {
		t.Fatalf("a disabled endpoint got %d deliveries", n)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("deleted endpoint: %s", r)
	}
}

