// publicEndpoint returns an endpoint as the API shows it: without the previous secret, which only signs deliveries for a while
// after a rotation.
func publicEndpoint(ep store.WebhookEndpoint) store.WebhookEndpoint {
	ep.PreviousSecret = ""
	return ep
}

func (s *Server) listEndpoints(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	eps := s.store.WebhookEndpoints(p.OrgID)
	for i := range eps {
