// refSig computes the v1 signature of "<t>.<body>" independently of the package.
func refSig(secret string, ts int64, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	fmt.Fprintf(m, "%d.", ts)
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

func TestSignatureHeader(t *testing.T) {
	body := []byte(`{"id":"evt_1"}`)
	at := time.Unix(1700000000, 0)
	got := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, at, body)
	want := "t=1700000000,v1=" + refSig("whsec_new", 1700000000, body) + ",v1=" + refSig("whsec_old", 1700000000, body)
	if got != want {
		t.Fatalf("SignatureHeader = %s\nwant %s", got, want)
	}
	if err := webhooks.Verify(body, got, []string{"whsec_old"}, 0, at); err != nil {
		t.Fatal(err)
	}
}

func TestVerify(t *testing.T) {
	const T = int64(1700000000)
	now := time.Unix(T, 0)
	body := []byte(`{"id":"evt_1"}`)
	sig := func(secret string, ts int64) string { return refSig(secret, ts, body) }
	cases := []struct {
		name    string
		header  string
		secrets []string
		tol     time.Duration
		want    error
	}{
		{"current secret", fmt.Sprintf("t=%d,v1=%s", T, sig("whsec_a", T)), []string{"whsec_a"}, 0, nil},
		{"spaces, order and unknown keys", fmt.Sprintf(" v0=zz , v1=%s ,t = %d", sig("whsec_a", T), T), []string{"whsec_a"}, 0, nil},
		{"previous secret's v1", fmt.Sprintf("t=%d,v1=%s,v1=%s", T, sig("whsec_new", T), sig("whsec_old", T)), []string{"whsec_old"}, 0, nil},
		{"any of several secrets", fmt.Sprintf("t=%d,v1=%s", T, sig("whsec_a", T)), []string{"whsec_x", "whsec_a"}, 0, nil},
		{"empty header", "", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"blank header", "   ", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"pair without =", fmt.Sprintf("t=%d,v1", T), []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"empty pair", fmt.Sprintf("t=%d,,v1=%s", T, sig("whsec_a", T)), []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"t not an integer", fmt.Sprintf("t=soon,v1=%s", sig("whsec_a", T)), []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
