		{"a given tolerance", fmt.Sprintf("t=%d,v1=%s", T-59, sig("whsec_a", T-59)), []string{"whsec_a"}, time.Minute, nil},
		{"outside a given tolerance", fmt.Sprintf("t=%d,v1=%s", T-61, sig("whsec_a", T-61)), []string{"whsec_a"}, time.Minute, webhooks.ErrTimestampTolerance},
		{"no v1", fmt.Sprintf("t=%d", T), []string{"whsec_a"}, 0, webhooks.ErrNoSignature},
		{"wrong secret", fmt.Sprintf("t=%d,v1=%s", T, sig("whsec_b", T)), []string{"whsec_a"}, 0, webhooks.ErrSignatureMismatch},
		{"no secrets", fmt.Sprintf("t=%d,v1=%s", T, sig("whsec_a", T)), nil, 0, webhooks.ErrSignatureMismatch},
		{"timestamp is signed", fmt.Sprintf("t=%d,v1=%s", T+1, sig("whsec_a", T)), []string{"whsec_a"}, 0, webhooks.ErrSignatureMismatch},
		{"v1 that is not a signature", fmt.Sprintf("t=%d,v1=abc", T), []string{"whsec_a"}, 0, webhooks.ErrSignatureMismatch},
	}
	for _, c := range cases {
		err := webhooks.Verify(body, c.header, c.secrets, c.tol, now)
		if c.want == nil && err != nil {
			t.Errorf("%s: Verify = %v", c.name, err)
		} else if c.want != nil && !errors.Is(err, c.want) {
			t.Errorf("%s: Verify = %v, want %v", c.name, err, c.want)
		}
	}
	header := fmt.Sprintf("t=%d,v1=%s", T, sig("whsec_a", T))
	if err := webhooks.Verify([]byte(`{"id":"evt_2"}`), header, []string{"whsec_a"}, 0, now); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Errorf("a changed body: Verify = %v", err)
	}
}

func TestSigningSecrets(t *testing.T) {
	rotated := time.Unix(1700000000, 0)
	ep := store.WebhookEndpoint{Secret: "whsec_new", PreviousSecret: "whsec_old", SecretRotatedAt: &rotated}
	for _, c := range []struct {
		after time.Duration
		want  []string
	}{
		{0, []string{"whsec_new", "whsec_old"}},
		{24*time.Hour - time.Second, []string{"whsec_new", "whsec_old"}},
		{24 * time.Hour, []string{"whsec_new"}},
	} {
		if got := webhooks.SigningSecrets(ep, rotated.Add(c.after)); fmt.Sprint(got) != fmt.Sprint(c.want) {
			t.Errorf("%v after the rotation: SigningSecrets = %v, want %v", c.after, got, c.want)
		}
	}
	if got := webhooks.SigningSecrets(store.WebhookEndpoint{Secret: "whsec_a"}, rotated); fmt.Sprint(got) != "[whsec_a]" {
		t.Errorf("never rotated: SigningSecrets = %v", got)
	}
}

