func TestRotateSecret(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	path := "/v1/webhook-endpoints/" + ep.ID + "/rotate-secret"
	first := ep.Secret

	rotate := func() string {
		t.Helper()
		r := e.Do("POST", path, e.Acme.Key, nil)
		if r.Code != http.StatusOK {
			t.Fatalf("rotate: %s", r)
		}
		if _, ok := r.Map(t)["previous_secret"]; ok {
			t.Fatal("the answer shows the previous secret")
		}
		var rotated store.WebhookEndpoint
		if err := json.Unmarshal(r.Body.Bytes(), &rotated); err != nil {
			t.Fatal(err)
		}
		if !strings.HasPrefix(rotated.Secret, "whsec_") || len(rotated.Secret) != len("whsec_")+32 || rotated.Secret == first {
			t.Fatalf("rotated secret = %q", rotated.Secret)
		}
		return rotated.Secret
	}
	// deliver sends one event and returns the request the receiver got.
	deliver := func() apitest.Request {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if _, err := e.Webhooks.RunDue(ctx); err != nil {
			t.Fatal(err)
		}
		reqs := e.HTTP.Requests()
		return reqs[len(reqs)-1]
	}
	// signedBy reports whether the request's signature verifies with secret.
	signedBy := func(r apitest.Request, secret string) bool {
		return webhooks.Verify(r.Body, r.Header.Get("Tally-Signature"), []string{secret}, 0, e.Clock.Now()) == nil
	}

	second := rotate()
	r := deliver()
	if n := strings.Count(r.Header.Get("Tally-Signature"), "v1="); n != 2 || !signedBy(r, second) || !signedBy(r, first) {
		t.Fatalf("after a rotation: signature %q", r.Header.Get("Tally-Signature"))
	}

	e.Clock.Advance(24 * time.Hour)
	third := rotate()
	r = deliver()
	if n := strings.Count(r.Header.Get("Tally-Signature"), "v1="); n != 2 || !signedBy(r, third) || !signedBy(r, second) || signedBy(r, first) {
		t.Fatalf("after a second rotation: signature %q", r.Header.Get("Tally-Signature"))
	}

	e.Clock.Advance(24 * time.Hour)
	r = deliver()
	if n := strings.Count(r.Header.Get("Tally-Signature"), "v1="); n != 1 || !signedBy(r, third) || signedBy(r, second) {
		t.Fatalf("24 hours after the rotation: signature %q", r.Header.Get("Tally-Signature"))
	}

	if r := e.Do("POST", "/v1/webhook-endpoints/we_missing/rotate-secret", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("unknown endpoint: %s", r)
	}
}

