222	// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
223	// type. The deliveries are sent by RunDue.
224	func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
225		raw, err := json.Marshal(data)
226		if err != nil {
227			return err
228		}
229		now := s.clock.Now()
230		e, err := s.store.AddEvent(orgID, eventType, raw, now)
231		if err != nil {
232			return err
233		}
234		for _, ep := range s.store.WebhookEndpoints(orgID) {
235			if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
236				continue
237			}
238			next := now
239			if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
240				return err
241			}
242		}
243		return nil
244	}
