246	// RunDue attempts every delivery that is due and returns how many it attempted. Each delivery is attempted once: an answer
247	// with a 2xx status marks it succeeded, anything else failed.
248	func (s *Service) RunDue(ctx context.Context) (int, error) {
249		n := 0
250		for _, d := range s.store.DueDeliveries(s.clock.Now()) {
251			if err := ctx.Err(); err != nil {
252				return n, err
253			}
254			s.deliver(ctx, d)
255			n++
256		}
257		return n, nil
258	}
