268	func (s *Service) deliver(ctx context.Context, d store.Delivery) {
269		status, errText := 0, ""
270		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
271		e, eok := s.store.EventByID(d.EventID)
272		switch {
273		case !ok || !ep.Enabled:
274			errText = "the endpoint is disabled or was deleted"
275		case !eok:
276			errText = "the event no longer exists"
277		default:
278			status, errText = s.send(ctx, ep, e)
279		}
280		now := s.clock.Now()
281		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
282			d.Attempts++
283			d.LastAttemptAt = &now
284			d.NextAttemptAt = nil
285			d.ResponseStatus = status
286			d.Error = errText
287			if errText == "" {
288				d.Status = store.DeliverySucceeded
289			} else {
290				d.Status = store.DeliveryFailed
291			}
292			return nil
293		})
294	}
