296	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
297	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
298		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
299		if err != nil {
300			return 0, err.Error()
301		}
302		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
303		defer cancel()
304		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
305		if err != nil {
306			return 0, err.Error()
307		}
308		req.Header.Set("Content-Type", "application/json")
309		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
310		req.Header.Set("Tally-Event-Id", e.ID)
311		req.Header.Set("Tally-Event-Type", e.Type)
312		now := s.clock.Now()
313		req.Header.Set("Tally-Signature", SignatureHeader(SigningSecrets(ep, now), now, body))
314		resp, err := s.doer.Do(req)
315		if err != nil {
316			return 0, err.Error()
317		}
318		defer resp.Body.Close()
319		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
320		if resp.StatusCode < 200 || resp.StatusCode > 299 {
321			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
322		}
323		return resp.StatusCode, ""
324	}
