52	func (s *Store) UpdateWebhookEndpoint(orgID, id string, f func(*WebhookEndpoint) error) (WebhookEndpoint, error) {
53		s.mu.Lock()
54		defer s.mu.Unlock()
55		old, ok := s.endpoints[id]
56		if !ok || old.OrgID != orgID {
57			return WebhookEndpoint{}, ErrNotFound
58		}
59		ep := copyEndpoint(old)
60		if err := f(&ep); err != nil {
61			return WebhookEndpoint{}, err
62		}
63		ep.ID, ep.OrgID, ep.CreatedAt = old.ID, old.OrgID, old.CreatedAt
64		if len(ep.Events) == 0 {
65			return WebhookEndpoint{}, invalid("an endpoint needs at least one event type")
66		}
67		s.endpoints[id] = copyEndpoint(ep)
68		return copyEndpoint(ep), nil
69	}
70	
71	// DeleteWebhookEndpoint removes an endpoint and its pending deliveries.
72	func (s *Store) DeleteWebhookEndpoint(id string) error {
73		s.mu.Lock()
74		defer s.mu.Unlock()
75		if _, ok := s.endpoints[id]; !ok {
76			return ErrNotFound
77		}
78		delete(s.endpoints, id)
79		for did, d := range s.delivs {
80			if d.EndpointID == id && d.Status == DeliveryPending {
81				delete(s.delivs, did)
82			}
83		}
84		return nil
85	}
86	
87	func copyEndpoint(ep WebhookEndpoint) WebhookEndpoint {
88		ep.Events = append([]string(nil), ep.Events...)
89		if ep.SecretRotatedAt != nil {
90			t := *ep.SecretRotatedAt
91			ep.SecretRotatedAt = &t
92		}
93		return ep
94	}
95	
96	// AddEvent records an event.
97	func (s *Store) AddEvent(orgID, typ string, data json.RawMessage, now time.Time) (Event, error) {
98		s.mu.Lock()
99		defer s.mu.Unlock()
100		if _, ok := s.orgs[orgID]; !ok {
101			return Event{}, ErrNotFound
102		}
103		e := Event{ID: s.newID("evt"), OrgID: orgID, Type: typ, Data: append(json.RawMessage(nil), data...), CreatedAt: now.UTC()}
104		s.events[e.ID] = e
105		return e, nil
106	}
107	
108	// Event returns one of an organization's events.
109	func (s *Store) Event(orgID, id string) (Event, bool) {
110		s.mu.Lock()
111		defer s.mu.Unlock()
112		e, ok := s.events[id]
113		if !ok || e.OrgID != orgID {
114			return Event{}, false
115		}
116		return e, true
117	}
118	
119	// EventByID returns an event of any organization (the webhook sender).
120	func (s *Store) EventByID(id string) (Event, bool) {
121		s.mu.Lock()
122		defer s.mu.Unlock()
123		e, ok := s.events[id]
124		return e, ok
125	}
126	
127	// Events returns an organization's events, oldest first, only those of one type when typ is set.
128	func (s *Store) Events(orgID, typ string) []Event {
129		s.mu.Lock()
130		defer s.mu.Unlock()
131		out := []Event{}
132		for _, e := range s.events {
133			if e.OrgID == orgID && (typ == "" || e.Type == typ) {
134				out = append(out, e)
135			}
136		}
137		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
138		return out
139	}
140	
141	// CreateDelivery queues an event for an endpoint.
142	func (s *Store) CreateDelivery(d Delivery, now time.Time) (Delivery, error) {
143		s.mu.Lock()
144		defer s.mu.Unlock()
145		ep, ok := s.endpoints[d.EndpointID]
146		if !ok || ep.OrgID != d.OrgID {
147			return Delivery{}, ErrNotFound
148		}
149		if e, ok := s.events[d.EventID]; !ok || e.OrgID != d.OrgID {
150			return Delivery{}, ErrNotFound
151		}
152		d.ID = s.newID("del")
153		d.CreatedAt = now.UTC()
154		if d.Status == "" {
155			d.Status = DeliveryPending
156		}
157		s.delivs[d.ID] = copyDelivery(d)
158		return copyDelivery(d), nil
159	}
160	
161	// Delivery returns a delivery of any organization (the webhook sender).
162	func (s *Store) Delivery(id string) (Delivery, bool) {
163		s.mu.Lock()
164		defer s.mu.Unlock()
165		d, ok := s.delivs[id]
166		return copyDelivery(d), ok
167	}
168	
169	// Deliveries returns an organization's deliveries to one endpoint, oldest first.
170	func (s *Store) Deliveries(orgID, endpointID string) []Delivery {
171		s.mu.Lock()
172		defer s.mu.Unlock()
173		out := []Delivery{}
174		for _, d := range s.delivs {
175			if d.OrgID == orgID && d.EndpointID == endpointID {
176				out = append(out, copyDelivery(d))
177			}
178		}
179		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
180		return out
181	}
182	
183	// DueDeliveries returns the pending deliveries of every organization whose next attempt is due by now, oldest first.
184	func (s *Store) DueDeliveries(now time.Time) []Delivery {
185		s.mu.Lock()
186		defer s.mu.Unlock()
187		out := []Delivery{}
188		for _, d := range s.delivs {
189			if d.Status == DeliveryPending && d.NextAttemptAt != nil && !d.NextAttemptAt.After(now) {
190				out = append(out, copyDelivery(d))
191			}
192		}
193		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
194		return out
195	}
196	
197	// UpdateDelivery changes a delivery with f.
198	func (s *Store) UpdateDelivery(id string, f func(*Delivery) error) (Delivery, error) {
199		s.mu.Lock()
200		defer s.mu.Unlock()
201		old, ok := s.delivs[id]
202		if !ok {
203			return Delivery{}, ErrNotFound
204		}
205		d := copyDelivery(old)
206		if err := f(&d); err != nil {
207			return Delivery{}, err
208		}
209		d.ID, d.OrgID, d.EndpointID, d.EventID, d.CreatedAt = old.ID, old.OrgID, old.EndpointID, old.EventID, old.CreatedAt
210		s.delivs[id] = copyDelivery(d)
211		return copyDelivery(d), nil
212	}
213	
214	func copyDelivery(d Delivery) Delivery {
215		for _, p := range []**time.Time{&d.NextAttemptAt, &d.LastAttemptAt} {
216			if *p != nil {
217				t := **p
218				*p = &t
219			}
220		}
221		return d
222	}
